
const { Brand, Product, sequelize } = require('../models');
const { Op } = require('sequelize');

// ============================================
// BRAND CRUD OPERATIONS
// ============================================

/**
 * Create a new brand (Admin only)
 * ✅ NO ID sent - auto-generated by database
 */
exports.createBrand = async (req, res) => {
  try {
    const { name, logo, description, isActive } = req.body;

    // Validate required fields
    if (!name || !name.trim()) {
      return res.status(400).json({
        success: false,
        message: 'Brand name is required'
      });
    }

    // Check if brand already exists (case-insensitive)
    const existingBrand = await Brand.findOne({
      where: { name: { [Op.iLike]: name.trim() } }
    });

    if (existingBrand) {
      return res.status(400).json({
        success: false,
        message: 'Brand with this name already exists'
      });
    }

    // Create brand - ✅ NO ID in request
    const brand = await Brand.create({
      name: name.trim(),
      logo: logo || null,
      description: description || null,
      isActive: isActive !== undefined ? isActive : true
    });

    res.status(201).json({
      success: true,
      message: 'Brand created successfully',
      brand
    });
  } catch (error) {
    console.error('Error creating brand:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to create brand'
    });
  }
};

/**
 * Get all brands (Public - only active)
 */
exports.getAllBrands = async (req, res) => {
  try {
    const { search, limit = 100, page = 1 } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);
    
    let where = { isActive: true };
    
    if (search) {
      where.name = { [Op.iLike]: `%${search}%` };
    }

    const { count, rows } = await Brand.findAndCountAll({
      where,
      order: [['name', 'ASC']],
      limit: parseInt(limit),
      offset
    });

    // Get product counts for each brand
    const brandsWithCount = await Promise.all(
      rows.map(async (brand) => {
        const productCount = await Product.count({
          where: { brandId: brand.id }
        });
        return {
          ...brand.toJSON(),
          productCount
        };
      })
    );

    res.status(200).json({
      success: true,
      brands: brandsWithCount,
      pagination: {
        total: count,
        page: parseInt(page),
        totalPages: Math.ceil(count / parseInt(limit))
      }
    });
  } catch (error) {
    console.error('Error fetching brands:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to fetch brands'
    });
  }
};

