/**
 * Get a single brand by ID with its products
 */
exports.getBrandById = async (req, res) => {
  try {
    const { id } = req.params;
    
    // Validate ID
    if (!id || isNaN(id)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid brand ID'
      });
    }

    const brand = await Brand.findByPk(id, {
      include: [{
        model: Product,
        as: 'products',
        attributes: ['id', 'title', 'name', 'price', 'oldPrice', 'discount', 'description', 'category', 'productCategory', 'color', 'size', 'image', 'stock', 'rating', 'isNewArrival', 'isOnSale', 'createdAt']
      }]
    });

    if (!brand) {
      return res.status(404).json({
        success: false,
        message: 'Brand not found'
      });
    }

    const brandData = brand.toJSON();
    brandData.productCount = brandData.products?.length || 0;

    res.status(200).json({
      success: true,
      brand: brandData
    });
  } catch (error) {
    console.error('Error fetching brand by ID:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to fetch brand'
    });
  }
};

/**
 * Get products for a specific brand
 */
exports.getBrandProducts = async (req, res) => {
  try {
    const { id } = req.params;
    
    if (!id || isNaN(id)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid brand ID'
      });
    }

    const brand = await Brand.findByPk(id, {
      attributes: ['id', 'name', 'logo']
    });

    if (!brand) {
      return res.status(404).json({
        success: false,
        message: 'Brand not found'
      });
    }

    const products = await Product.findAll({
      where: { brandId: id },
      order: [['createdAt', 'DESC']],
      include: [{
        model: Brand,
        as: 'brand',
        attributes: ['id', 'name', 'logo']
      }]
    });

    res.status(200).json({
      success: true,
      brand: brand.name,
      brandId: brand.id,
      productCount: products.length,
      products
    });
  } catch (error) {
    console.error('Error fetching brand products:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to fetch brand products'
    });
  }
};

/**
 * Update a brand (Admin only)
 */
exports.updateBrand = async (req, res) => {
  try {
    const { id } = req.params;
    const { name, logo, description, isActive } = req.body;

    // Validate ID
    if (!id || isNaN(id)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid brand ID'
      });
    }

    const brand = await Brand.findByPk(id);
    if (!brand) {
      return res.status(404).json({
        success: false,
        message: 'Brand not found'
      });
    }

    // Check if name is being changed and if it conflicts
    if (name && name.trim() !== brand.name) {
      const existingBrand = await Brand.findOne({
        where: { 
          name: { [Op.iLike]: name.trim() },
          id: { [Op.ne]: id }
        }
      });

      if (existingBrand) {
        return res.status(400).json({
          success: false,
          message: 'Brand name already exists'
        });
      }
    }

    // Build update data
    const updateData = {};
    if (name) updateData.name = name.trim();
    if (logo !== undefined) updateData.logo = logo;
    if (description !== undefined) updateData.description = description;
    if (isActive !== undefined) updateData.isActive = isActive;
    updateData.updatedAt = new Date();

    await brand.update(updateData);

    // Fetch updated brand
    const updatedBrand = await Brand.findByPk(id);

    res.status(200).json({
      success: true,
      message: 'Brand updated successfully',
      brand: updatedBrand
    });
  } catch (error) {
    console.error('Error updating brand:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to update brand'
    });
  }
};

/**
 * Delete a brand (Admin only)
 * ✅ Only if no products are associated
 */
exports.deleteBrand = async (req, res) => {
  try {
    const { id } = req.params;

    if (!id || isNaN(id)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid brand ID'
      });
    }

    const brand = await Brand.findByPk(id);
    if (!brand) {
      return res.status(404).json({
        success: false,
        message: 'Brand not found'
      });
    }

    // Check if brand has products
    const productCount = await Product.count({
      where: { brandId: id }
    });

    if (productCount > 0) {
      return res.status(400).json({
        success: false,
        message: `Cannot delete brand with ${productCount} products. Please reassign or delete products first.`
      });
    }

    // Soft delete (paranoid: true)
    await brand.destroy();

    res.status(200).json({
      success: true,
      message: 'Brand deleted successfully'
    });
  } catch (error) {
    console.error('Error deleting brand:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to delete brand'
    });
  }
};

/**
 * Get brands with product count only (lightweight)
 */
exports.getBrandsWithProductCount = async (req, res) => {
  try {
    const brands = await Brand.findAll({
      where: { isActive: true },
      order: [['name', 'ASC']]
    });

    const brandsWithCount = await Promise.all(
      brands.map(async (brand) => {
        const count = await Product.count({
          where: { brandId: brand.id }
        });
        return {
          id: brand.id,
          name: brand.name,
          logo: brand.logo,
          productCount: count
        };
      })
    );

    res.status(200).json({
      success: true,
      brands: brandsWithCount
    });
  } catch (error) {
    console.error('Error fetching brands with count:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to fetch brands'
    });
  }
};

/**
 * Toggle brand active status (Admin only)
 */
exports.toggleBrandStatus = async (req, res) => {
  try {
    const { id } = req.params;

    if (!id || isNaN(id)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid brand ID'
      });
    }

    const brand = await Brand.findByPk(id);
    if (!brand) {
      return res.status(404).json({
        success: false,
        message: 'Brand not found'
      });
    }

    await brand.update({
      isActive: !brand.isActive,
      updatedAt: new Date()
    });

    res.status(200).json({
      success: true,
      message: `Brand ${brand.isActive ? 'activated' : 'deactivated'} successfully`,
      brand
    });
  } catch (error) {
    console.error('Error toggling brand status:', error);
    res.status(500).json({
      success: false,
      message: error.message || 'Failed to toggle brand status'
    });
  }
};


